var availabilityForCombatAction = (input) => {
  const {
    state,
    actor,
    action,
    nearby,
    murderTraitGateMinSurvival,
    murderReputationGateMax,
    resolveTarget,
    isEnemy
  } = input;
  if (action.actionType === "fight") {
    const target = resolveTarget(
      actor,
      action.payload.targetId,
      nearby,
      true
    );
    return target ? { available: true, blockedReasons: [] } : { available: false, blockedReasons: ["Need an enemy target"] };
  }
  if (action.actionType === "flee") {
    const nearbyEnemy = nearby.find((target) => isEnemy(actor, target));
    if (!nearbyEnemy) {
      return {
        available: false,
        blockedReasons: ["Need an active encounter"]
      };
    }
    const direction = String(action.payload.direction ?? "");
    if (!direction) {
      return { available: false, blockedReasons: ["Need flee direction"] };
    }
    const next = dungeonStep(
      state.dungeon,
      actor.depth,
      actor.roomId,
      direction,
      actor.entityKind === "hostile" || actor.entityKind === "boss" ? [ROOM_FEATURE_RUNE_FORGE] : []
    );
    return next ? { available: true, blockedReasons: [] } : { available: false, blockedReasons: ["flee_blocked"] };
  }
  if (action.actionType === "murder") {
    const target = resolveTarget(
      actor,
      action.payload.targetId,
      nearby,
      true
    );
    if (!target) {
      return { available: false, blockedReasons: ["Need enemy target"] };
    }
    if (Number(actor.narrativeStats.Survival ?? 0) < murderTraitGateMinSurvival) {
      return {
        available: false,
        blockedReasons: ["Trait gate failed (Survival too low)"]
      };
    }
    const factionGate = actor.faction === "laughing_face" || actor.reputation <= murderReputationGateMax;
    return factionGate ? { available: true, blockedReasons: [] } : {
      available: false,
      blockedReasons: ["Faction/reputation gate failed"]
    };
  }
  return null;
};
