// src/escape-the-dungeon/engine/game-runtime-views.ts
var buildInventoryStatus = (player, equippedSlotForItem) => {
  return player.inventory.map((item) => ({
    itemId: item.itemId,
    name: item.name,
    rarity: item.rarity,
    tags: [...item.tags],
    equipped: equippedSlotForItem(item.itemId) !== null,
    equippedSlot: equippedSlotForItem(item.itemId)
  }));
};
var buildEquippedSpellStatus = (slots) => {
  return slots.map((slot) => ({
    slotIndex: slot.slotIndex,
    skillId: slot.skillId,
    name: slot.name
  }));
};
var buildSpellPoolStatus = (spells) => {
  return spells.map((spell) => ({
    skillId: spell.skillId,
    name: spell.name,
    branch: spell.branch,
    isEquipped: spell.isEquipped,
    slotIndex: spell.slotIndex
  }));
};
var buildAuthoredSpellProgressStatus = (skillIds, authoredSpellStatus) => {
  return Object.fromEntries(
    skillIds.map((skillId) => {
      const runtime = authoredSpellStatus(skillId);
      return [
        skillId,
        runtime ? {
          level: runtime.level,
          useCount: runtime.useCount,
          affinityBonus: runtime.affinityBonus,
          runeCombo: runtime.runeCombo,
          evolutions: runtime.evolutions.map((evolution) => ({
            evolutionId: evolution.evolutionId,
            sourceSpellId: evolution.sourceSpellId,
            resultSpellId: evolution.resultSpellId,
            available: evolution.available,
            blockedReasons: evolution.blockedReasons
          }))
        } : null
      ];
    })
  );
};
var buildQuestStatus = (quests) => {
  return Object.fromEntries(
    Object.entries(quests).map(([key, quest]) => [
      key,
      {
        progress: quest.progress,
        required: quest.requiredProgress,
        complete: quest.isComplete
      }
    ])
  );
};
var buildDialogueProgressStatus = (dialogueProgress) => {
  return {
    sequence: dialogueProgress.sequence,
    lastOptionId: dialogueProgress.lastOptionId,
    lastSceneId: dialogueProgress.lastSceneId,
    visitedOptionCount: dialogueProgress.visitedOptionIds.length,
    visitedSceneCount: dialogueProgress.visitedSceneIds.length,
    recent: dialogueProgress.history.slice(-5)
  };
};
var buildLookSummary = (input) => {
  const roomVector = input.roomVector.map(
    (row) => `${row.trait}${row.value >= 0 ? "+" : ""}${row.value.toFixed(2)}`
  ).join(", ");
  return [
    input.roomDescription,
    `Exits: ${input.exits.join(", ") || "none"}`,
    `Nearby: ${input.nearby.join(", ") || "none"}`,
    `Archetype: ${input.archetypeHeading}`,
    `Mount: ${input.mountLabel}`,
    `Room vector: ${roomVector || "neutral"}`,
    `Available actions: ${input.availableActions.join(", ") || "none"}`
  ].join("\n");
};

// src/escape-the-dungeon/engine/game-state-persistence.ts
var createEmptyDialogueProgress = () => ({
  sequence: 0,
  lastOptionId: null,
  lastSceneId: null,
  visitedOptionIds: [],
  visitedSceneIds: [],
  history: []
});
var captureSnapshotState = (state, rngState, seenCutscenes) => {
  state.rngState = rngState;
  state.seenCutscenes = seenCutscenes;
  return cloneState(state);
};
var restoreSnapshotState = (snapshot) => {
  const state = cloneState(snapshot);
  if (!state.dialogueProgress) {
    state.dialogueProgress = createEmptyDialogueProgress();
  }
  if (typeof state.mountSummoned !== "boolean") {
    state.mountSummoned = false;
  }
  if (typeof state.streamActive !== "boolean") {
    state.streamActive = false;
  }
  if (!Array.isArray(state.summonFormSpellIds)) {
    state.summonFormSpellIds = [];
  }
  if (!state.initiativeMeters) {
    state.initiativeMeters = {};
  }
  if (!Array.isArray(state.lastInitiativeOrder)) {
    state.lastInitiativeOrder = [];
  }
  for (const entity of Object.values(state.entities)) {
    entity.entityTypeId = canonicalEntityTypeId(entity.entityTypeId, entity.entityKind);
    entity.occupationId = canonicalOccupationId(entity.occupationId, entity.entityKind);
    entity.occupationName = occupationLabel(entity.occupationId);
    entity.partyRoleId = canonicalPartyRoleId(entity.partyRoleId, entity.entityKind);
    entity.partyRoleName = partyRoleLabel(entity.partyRoleId);
    entity.summonedBySkillId = typeof entity.summonedBySkillId === "string" ? entity.summonedBySkillId : null;
    normalizeEntityStats(entity);
  }
  return state;
};

// src/escape-the-dungeon/engine/systems/history.ts
